function validateProject(p){if(!p||p.version!==1||!Array.isArray(p.cuts)||p.cuts.length>MAX_CUTS)throw Error('올바른 SCROLL STUDIO 프로젝트가 아닙니다.');if(!Number.isFinite(p.width)||p.width<320||p.width>8192)throw Error('캔버스 폭이 올바르지 않습니다.');p.bleed=[0,50,100].includes(p.bleed)?p.bleed:0;p.pageHeight=Number.isInteger(p.pageHeight)&&p.pageHeight>=320&&p.pageHeight<=20000?p.pageHeight:20000;p.dpi=[72,150,300,600].includes(p.dpi)?p.dpi:72;if(p.format==='comic'){const checked=comicConfig({dpi:p.dpi,comic:p.comic});p.comic=checked.comic;if(Math.abs(checked.width-p.width)>1||Math.abs(checked.pageHeight-p.pageHeight)>1)throw Error('출판만화 용지 크기와 픽셀 크기가 일치하지 않습니다.');}p.assets=p.assets||{};if(Object.keys(p.assets).length>100)throw Error('배경은 100개까지 지원합니다.');for(let a of Object.values(p.assets))if(typeof a.data!=='string'||!a.data.startsWith('data:'))throw Error('외부 배경 링크는 지원하지 않습니다.');if(p.pages){if(!Array.isArray(p.pages)||!p.pages.length||p.pages.length>MAX_PAGES||new Set(p.pages.map(x=>x.id)).size!==p.pages.length)throw Error('페이지 정보가 올바르지 않습니다.');for(const pg of p.pages)if(p.cuts.filter(c=>c.pageId===pg.id&&c.pageBase).length!==1)throw Error('페이지 러프가 없습니다.');for(const c of p.cuts)if(!p.pages.some(pg=>pg.id===c.pageId)||!Number.isFinite(c.x)||!Number.isFinite(c.y)||c.x<0||c.y<0||c.y+c.height>p.pageHeight+1e-6||c.x+p.width*c.width/100>p.width+1)throw Error('컷의 페이지 위치가 올바르지 않습니다.');}for(let c of p.cuts){validateFrameGeometry(c);repairInheritedGuide(c);if(!Number.isFinite(c.height)||c.height<160||c.height>(c.pageBase?20000:5000)+1e-6||!Number.isFinite(c.gap)||c.gap<0||c.gap>3000)throw Error('컷 크기가 올바르지 않습니다.');c.width=clamp(Number(c.width)||90,p.pages?Math.min(4,8000/p.width):40,100);c.visible=c.visible||{background:true,sketch:true,text:true};if(c.frame?.path&&(!Array.isArray(c.frame.path)||c.frame.path.length<3||c.frame.path.length>2000||c.frame.path.some(pt=>!Array.isArray(pt)||pt.length!==2||pt.some(v=>!Number.isFinite(v)||v<0||v>1))))throw Error('컷 테두리 경로가 올바르지 않습니다.');c.strokes=c.strokes||[];c.bubbles=c.bubbles||[];c.scene=c.scene||defaultScene();if(c.scene.people.length>30)throw Error('컷당 인물은 30명까지 지원합니다.');for(const s of [c.background,c.guide])if(s&&!s.startsWith('data:image/'))throw Error('지원하지 않는 이미지입니다.');}return validateLayerData(p);}
function library(){if(!$('library')){let d=document.createElement('dialog');d.id='library';d.innerHTML='<div class="modal-head"><div><span class="eyebrow">EPISODE ASSETS</span><h2>이번 화의 배경 라이브러리</h2></div><button id="closeLibrary">✕</button></div><p>한 번 불러온 배경을 모든 컷에서 사용합니다. 새 컷은 현재 컷의 배경과 인물을 이어받습니다.</p><button id="libraryImport" class="primary full">＋ 배경 파일 추가 · SKP / BLEND / GLB</button><div id="assetList"></div>';document.body.append(d);$('closeLibrary').onclick=()=>d.close();$('libraryImport').onclick=()=>{chooseModelFile('library');};}let list=$('assetList');list.replaceChildren();for(const [id,name]of [['room','스튜디오'],['interaction-room','상호작용 연습실 · 문 / 의자 / 침대'],['castle','성문 · 샘플'],['empty','빈 공간'],...Object.values(backgrounds.assets()).map(a=>[a.id,a.name])]){let el=document.createElement('div');el.className='asset-card';let b=document.createElement('b');b.textContent=name;let sm=document.createElement('small');sm.textContent=id.startsWith('local-')?'로컬 경량 배경 · 선택 시 불러오기':project.assets[id]?'불러온 배경 · 모든 컷에서 재사용':'기본 3D 공간';const credit=backgrounds.assets()[id]?.attribution;if(credit?.author&&credit?.license)sm.textContent+=' · '+credit.author+' · '+credit.license;b.append(sm);let btn=document.createElement('button');btn.textContent='이 컷에 배치';btn.onclick=async()=>{$('library').close();try{await openScene();if(editor?.isOpen)await editor.selectAsset(id);else toast('배경을 넣을 컷을 먼저 선택하세요.');}catch(error){toast('배경 로드 실패: '+error.message);}};el.append(b,btn);list.append(el);}if(!$('library').open)$('library').showModal();}
