function layoutPlacements(){let y=80;if(project.pages)return project.pages.flatMap((pg,i)=>project.cuts.filter(c=>c.pageId===pg.id).sort(frameOrder).map(c=>({cut:c,x:Math.round(c.x||0),y:i*project.pageHeight+(c.y||0)})));return project.cuts.map(c=>{const p={cut:c,y,x:Math.round((project.width+project.bleed)*(1-c.width/100)/2)};y+=c.height+c.gap;return p;});}
