setupBookManager({toast,pauseScene:()=>{if(editor?.isOpen)hideDock();},importGuide:async({image,item,start,end,name})=>{
 const w=project.width+project.bleed,h=Math.round((end-start)/item.width*w);if(h<160||h>5000)throw Error('콘티 컷 높이는 160–5000px입니다. 가져올 구간을 조절하세요.');if(project.cuts.length>=300)throw Error('프로젝트는 300컷까지 지원합니다.');
 const cv=canvas(w,h);cv.getContext('2d').drawImage(image,0,start/item.height*image.naturalHeight,image.naturalWidth,(end-start)/item.height*image.naturalHeight,0,0,w,h);
 checkpoint();const c=blankCut({...defaultScene(),asset:'empty',people:[]});c.width=100;c.height=h;c.name=name.replace(/\.clip$/i,'')+' · '+Math.round(start)+'–'+Math.round(end);c.background=cv.toDataURL();c.note='CLIP 저장 미리보기 가이드 · '+name+' / '+Math.round(start)+'–'+Math.round(end)+'px. 원본 레이어는 별도 CLIP에 있습니다.';c.reference={file:name,start,end,width:item.width,height:item.height};if(project.pages)Object.assign(c,{pageId:project.activePage,x:0,y:0});project.cuts.push(c);selected=c.id;if($('welcome').open)$('welcome').close();render();save();document.querySelector(`.panel-wrap[data-id="${c.id}"]`)?.scrollIntoView({block:'center'});toast('선택한 구간을 새 콘티 컷으로 가져왔습니다.');
}});
