document.addEventListener('scene-lineart',e=>{const c=project.cuts.find(c=>c.id===e.detail.cutId);if(!c)return;ensureLayers(c);const tones=e.detail.toneLayers||[];if(c.paintLayers.length+(tones.length?2:1)>30)return toast('선화·톤 레이어 공간이 부족합니다.');checkpoint();if(tones.length){const tid=uid();c.paintLayers.push({id:tid,name:'3D 툰 그림자 · 톤',opacity:100,visible:true,locked:false});for(const tone of tones)c.strokes.push({layerId:tid,points:[],fillRuns:tone.runs,rowHeight:1/e.detail.height,color:tone.color,opacity:100,size:1});}const id=uid();c.paintLayers.push({id,name:'3D 추출 선화',opacity:100,visible:true,locked:false});c.strokes.push({layerId:id,points:[],fillRuns:e.detail.runs,rowHeight:1/e.detail.height,color:'#000000',opacity:100,size:1});c.activeLayer=id;c.layerSettings.background.visible=false;c.layerSettings.guide.visible=false;render();save();toast(tones.length?'선화와 툰 그림자를 별도 레이어로 추가했습니다.':'3D 선화를 새 레이어로 추가했습니다.');});
